function getCurrentTime(ctx) {
  return ctx.elapsed * 1000;
}

function isCooldownActive(ctx) {
  const now = getCurrentTime(ctx);
  const last = ctx.variables.lastTiltTime;
  return (now - last) < ctx.variables.tiltCooldown;
}

export function handleCorrect(ctx) {
  const { variables } = ctx;
  if (isCooldownActive(ctx)) return;
  if (!variables.tiltArmed) return;

  variables.score++;
  variables.lastTiltTime = getCurrentTime(ctx);
  variables.tiltArmed = false;
  variables.lastTiltDirection = 'correct';
  nextCard(ctx);
}

export function handlePass(ctx) {
  const { variables } = ctx;
  if (isCooldownActive(ctx)) return;
  if (!variables.tiltArmed) return;

  variables.pass++;
  variables.lastTiltTime = getCurrentTime(ctx);
  variables.tiltArmed = false;
  variables.lastTiltDirection = 'pass';
  nextCard(ctx);
}

export function rearmTilt(ctx) {
  ctx.variables.tiltArmed = true;
  ctx.variables.lastTiltDirection = '';
}

function nextCard(ctx) {
  const { variables } = ctx;
  variables.currentCardIndex++;
  if (variables.currentCardIndex >= variables.deck.length) {
    variables.gameState = 'finished';
    variables.currentCard = 'GAME OVER';
  } else {
    variables.currentCard = variables.deck[variables.currentCardIndex];
  }
}

export function tickTimer(ctx) {
  const { variables } = ctx;
  variables.timer--;
  if (variables.timer <= 0) {
    variables.gameState = 'finished';
    variables.currentCard = 'TIME UP!';
  }
}
